      SUBROUTINE REVISE      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDWRDS.CIN'C--------------------------------------------------------------------------------      CHARACTER*15  LBTEST      INTEGER       TYPC, TYPCS      EQUIVALENCE   (FAKE,LAKE)CC      NUM = 1      N49 = 0      N55 = 0      N56 = 0      NNSAVE = 0C   70 I = ISTOR(NUM)      TYPE = IDATA(I)      LABLE = LABEL(NUM)C      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 49) GO TO 4900      IF (TYPE .EQ. 55) GO TO 5500      IF (TYPE .EQ. 56) GO TO 5600      GO TO 6100         2400 NBEG = 0      NEND = 0      NELM = 0      NDEF = 0      JDEF = IDATA(I+1)      IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) GO TO 6100      DO 2410 NN = 1, NEL      II = ISTOR(NN)      TYPC = IDATA(II)      LBTEST = LABEL(NN)      IF (TYPC .EQ. 24) THEN        JDEFC = IDATA(II+1)        IF (JDEFC .EQ. 1) NDEF = NDEF + 1        IF (JDEFC .EQ. 2) NDEF = NDEF - 1      ENDIF      IF (LBTEST .EQ. LABLE) THEN        TYPCS = TYPC        IF (TYPCS .EQ. 24) THEN          IF (JDEFC .EQ. 1) NBEG = NN          IF (JDEFC .EQ. 2) THEN            NEND = NN            GO TO 2420          ENDIF        ELSE          IF (NDEF .EQ. 0) THEN            NELM = NN            GO TO 2420          ENDIF        ENDIF        ENDIF 2410 CONTINUEC 2420 IF (TYPCS .EQ. 24) THEN        IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN          LAKE = NBEG          DATA(I+2) = FAKE          LAKE = NEND          DATA(I+3) = FAKE        ENDIF      ELSE         ISTOR(NUM) = ISTOR(NELM)      ENDIF      GO TO 6100      CC     PHONY TEMPORARY GLOBAL PARAMETERC 4900 N49 = 1      DO 4910 NN = 1, NEL      II = ISTOR(NN)      TYPC = IDATA(II)      LBTEST = LABEL(NN)      IF (TYPC .EQ. 30 .AND. LBTEST .EQ. LABEL(NUM)) THEN        N49 = 0        IIOLD = ISTOR(NUM) + 1        IISAVE = ISTOR(NN) + 1        GO TO 4920      ENDIF 4910 CONTINUE      WRITE (NOUT,9001) LABEL(NUM) 9001 FORMAT (' *** PARAMETER ', A15, ' NOT FOUND ***')      GO TO 6200C 4920 IIEL = ISTOR(NEL+1) - 1      DO 4930 II = 1, IIEL       IF (TIE(II) .EQ. 100) THEN        IF (IDATA(II) .EQ. IIOLD) THEN          LAKE = IISAVE          DATA(II) = FAKE          ENDIF      ENDIF 4930 CONTINUECC     PHONY TEMPORARY ELEMENT LABEL FOR ELEMENT PARAMETERC 5500 N55 = 1      NNSAVE = 0      DO 5510 NN = 1, NEL      II = ISTOR(NN)      TYPC = IDATA(II)      LBTEST = LABEL(NN)      IF (TYPC .NE. 55 .AND. LBTEST .EQ. LABEL(NUM)) THEN        NNSAVE = NN        N55 = 0        GO TO 6100      ENDIF 5510 CONTINUE      WRITE (NOUT,9002) LABEL(NUM) 9002 FORMAT (' *** ELEMENT LABEL ', A15, ' NOT FOUND ***')      GO TO 6200CC     PHONY TEMPORARY PARAMETER NAME FOR ELEMENT PARAMETERC 5600 N56 = 1      IF (NNSAVE .EQ. 0) THEN        WRITE (NOUT,9003) LABEL(NUM)        GO TO 6200      ENDIF      CALL SKETCH(NNSAVE)      IISAVE = ISTOR(NNSAVE)      NTYPE = IDATA(IISAVE)      ILEN = LENNB(LABEL(NUM))      CALL RDPARS(LABEL(NUM),ILEN,IEP)      IF (IEP .EQ. 0) THEN        WRITE (NOUT,9003) LABEL(NUM) 9003   FORMAT (' *** ELEMENT PARAMETER KEYWORD ',A15,     1          ' NOT RECOGNIZED ***')        GO TO 6200      ENDIF      IISAVE = IISAVE + IPTOJ(IEP)C      IIEL = ISTOR(NEL+1) - 1      DO 5610 III = 1, IIEL      IF (TIE(III) .EQ. 100) THEN        IF (IDATA(III) .EQ. I + 1) THEN          LAKE = IISAVE          DATA(III) = FAKE          N56 = 0        ENDIF      ENDIF 5610 CONTINUE      GO TO 6100CC     ADVANCE TO NEXT ELEMENTC 6100 NUM = NUM + 1      IF (NUM .LE. NEL - 1) GO TO 70C 6200 FLUSHL = N49 .GT. 0 .OR. N55 .GT. 0 .OR. N56 .GT. 0      RETURN      END      SUBROUTINE SEEDIT      INCLUDE 'ISEEDX.CIN'      INCLUDE 'NUMREP.CIN'C      CHARACTER*1     BLANK      DATA BLANK /' '/C      JS = 81      DO 10 J = 1, 80      JS = 81 - J      IF (NUMREP(JS:JS) .EQ. BLANK) GO TO 20   10 CONTINUE   20 IF (JS .GE. 65) THEN        DO 30 J = 65, JS        NUMREP(J:J) = '0'   30   CONTINUE      ENDIF      READ (NUMREP(65:80),9002) ISEEDX 9002 FORMAT (4I4)      ISEEDX(4) = 2*(ISEEDX(4)/2) + 1      RETURN      END